<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;use Illuminate\Database\Eloquent\SoftDeletes;
final class TenantBranch extends Model{use HasUuids,SoftDeletes;protected$fillable=['tenant_id','code','name','status','phone_e164','email','address','timezone','manager_user_id','parent_branch_id','capabilities'];protected function casts():array{return['address'=>'array','capabilities'=>'array'];}public function parent():BelongsTo{return$this->belongsTo(self::class,'parent_branch_id');}public function tenant():BelongsTo{return$this->belongsTo(Tenant::class);}public function manager():BelongsTo{return$this->belongsTo(User::class,'manager_user_id');}public function memberships():HasMany{return$this->hasMany(TenantMembership::class,'branch_id');}}
